from pathlib import Path
import numpy as np,json,shutil,sys
from scipy.ndimage import gaussian_filter,maximum_filter
from PIL import Image
D=Path(__file__).resolve().parent;W=D.parent;A=W/(sys.argv[1] if len(sys.argv)>1 else 'AR_core_fibers');C=W/'AS_wood_planes';C.mkdir(exist_ok=True);m=np.load(D/'readable_layers.npz')['medium_after'];h,w=m.shape;dx,dy=5.1/(w-1),1.3775/(h-1);angle=np.load(W/'final_fibers/broken_fiber_layers.npz')['angle'];M=np.load(W/'grain_hierarchy/detail_layers.npz')
def ss(a,b,v):q=np.clip((v-a)/(b-a),0,1);return q*q*(3-2*q)
smooth=gaussian_filter(m,(.006/dy,.018/dx));fy,fx=np.gradient(smooth,dy,dx);fxx=np.gradient(fx,dx,axis=1);fyy=np.gradient(fy,dy,axis=0);fxy=-np.gradient(fx,dy,axis=0);nx,ny=-np.sin(angle),np.cos(angle);curvature=nx*nx*fxx+2*nx*ny*fxy+ny*ny*fyy
depth=maximum_filter(-m,size=(int(.16/dy)|1,int(.24/dx)|1));depth=gaussian_filter(depth,(.015/dy,.04/dx));depth=np.maximum(depth,.004);broadness=np.sqrt(depth/np.maximum(abs(curvature),.1));convex=ss(.8,4,-curvature);broad=ss(.035,.065,broadness);mask=gaussian_filter(convex*broad,(.004/dy,.012/dx))
X,Y=np.meshgrid(np.linspace(-2.55,2.55,w,dtype='float32'),np.linspace(-.84,-2.2175,h,dtype='float32'));guard=1-ss(.0015,.009,-M['fractures']);away=ss(.28,.42,np.hypot(X+1.31,Y+1.35));edge=np.minimum.reduce([2.35-abs(X),Y+2.16,-.8625-Y]);mask*=guard*away*ss(.025,.09,edge)
ratio=np.clip(-m/depth,0,1);target=-depth*ratio**1.65;correction=np.clip((target-m)*mask*.72,0,.0045);correction=gaussian_filter(correction,(.0015/dy,.004/dx))*guard*away
s=np.load(A/'master_height.npz');H=s['height'];add=np.asarray(Image.fromarray(correction).resize((H.shape[1],H.shape[0]),Image.Resampling.BICUBIC),dtype='float32');full=np.minimum(H+add,0);add=full-H;geo=np.load(A/'surface.npz')['height'];lo=gaussian_filter(add,(.0038/(1.3775/(H.shape[0]-1)),.0038/(5.1/(H.shape[1]-1))));lo=np.asarray(Image.fromarray(lo).resize((geo.shape[1],geo.shape[0]),Image.Resampling.BICUBIC),dtype='float32');np.savez_compressed(C/'surface.npz',height=np.minimum(geo+lo,0));np.savez_compressed(C/'master_height.npz',height=full,delta=s['delta']+add)
for name in ['albedo.png','roughness.png','normal_masks.npz']:shutil.copy2(A/name,C/name)
np.savez_compressed(D/'broad_cap_layers.npz',curvature=curvature,broadness=broadness,mask=mask,correction=correction)
d=json.loads((A/'design.json').read_text());d.update(source='Organized hardwood with a continuous two dimensional profile correction limited to broad convex grain shoulders',cap_policy='Convex curvature and physical width select rounded caps; sharp edges, valley centers, core and primary fractures protected',profile_power=1.65,profile_blend=.72,correction_max=float(add.max()),new_fibers=0,new_cracks=0,height_min=float(full.min()));(C/'design.json').write_text(json.dumps(d,indent=2));print('Prepared selected broad caps',float(add.max()),flush=True)
